<?php
function stable_version(string $tag): ?string { return preg_match('/^v?((?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*))$/D',$tag,$m)?$m[1]:null; }
function select_stable_release(array $releases): ?array { $best=null;$version=null;foreach($releases as $r){$v=stable_version($r['tag_name']??'');if(!$v||!empty($r['draft'])||!empty($r['prerelease']))continue;if($version===null||version_compare($v,$version,'>')){$version=$v;$best=$r;}}return $best; }
function check_updates(bool $manual=false): array {
 $c=config();$installed=trim(file_get_contents(ROOT.'/VERSION'));$owner=$c['github_owner']??'';$repo=$c['github_repo']??'';$base=['installed'=>$installed,'newer'=>false];if(!$owner||!$repo)return $base+['message'=>'No repository configured. Set the GitHub owner and repository in Settings.'];
 $cache=private_dir().'/update-cache.json';$key=$owner.'/'.$repo;$saved=is_file($cache)?json_decode(file_get_contents($cache),true):null;if(!$manual&&$saved&&($saved['repository']??'')===$key&&time()-($saved['checked']??0)<3600)return $saved;
 try{$url='https://api.github.com/repos/'.rawurlencode($owner).'/'.rawurlencode($repo).'/releases?per_page=100';$context=stream_context_create(['http'=>['header'=>"User-Agent: VehicleTracker/$installed\r\nAccept: application/vnd.github+json\r\n",'timeout'=>12,'ignore_errors'=>false]]);$raw=@file_get_contents($url,false,$context);if($raw===false)throw new RuntimeException('GitHub unavailable, rate-limited, or repository inaccessible.');$releases=json_decode($raw,true,512,JSON_THROW_ON_ERROR);$best=select_stable_release($releases);$version=$best?stable_version($best['tag_name']):null;$out=$base+['message'=>'No published stable semantic-version release found.'];if($best){$asset=null;foreach($best['assets']??[] as $a)if(preg_match('/\.zip$/i',$a['name']??'')&&str_starts_with($a['browser_download_url']??'','https://github.com/')){$asset=$a;break;}$url=$asset['browser_download_url']??$best['zipball_url'];if(!preg_match('~^https://(api\.github\.com|github\.com)/~',$url))throw new RuntimeException('Untrusted release download URL.');$out=['installed'=>$installed,'latest'=>$version,'newer'=>version_compare($version,$installed,'>'),'release_url'=>$best['html_url'],'download_url'=>$url,'download_label'=>$asset?'Application ZIP: '.$asset['name']:'Tagged source ZIP (not a Windows executable)','message'=>'Stable release checked.'];}$out+=['checked'=>time(),'repository'=>$key];file_put_contents($cache,json_encode($out),LOCK_EX);return $out;
 }catch(Throwable $e){return $base+['message'=>$e->getMessage(),'offline'=>true];}
}
